package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class ReportNoUpdateProofTest {
 boolean mysql(){return false;}
 ReportNoUpdateFirstTest f;ReportNoUpdateProofService service;Clock clock;
 void setup()throws Exception{f=new ReportNoUpdateFirstTest(){@Override boolean mysql(){return ReportNoUpdateProofTest.this.mysql();}};f.setup();clock=Clock.fixed(f.original.receipt().recordedAt().plusNanos(1),ZoneOffset.UTC);compose();}
 void compose(){var base=f.f.f.data.nativeData().fixture().f();service=new ReportNoUpdateProofService(base.source,f.f.originals,base.writes,base.tx,clock);}
 @Test void ActualCommittedWholeNoInputDayGetsRealCeilingMicroFirstAndRestartPreservesIt()throws Exception{setup();assertNull(service.find(f.f.scope));var available=service.observe(f.f.scope);assertNotNull(available);assertEquals(f.original.receipt().recordedAt().plusNanos(1000),available.availableAt());assertEquals(f.original.input().inputHash(),available.inputHash());assertSame(available,f.f.f.rr(()->service.verifyObserved(available)));clock=mock(Clock.class);compose();assertEquals(available.availableAt(),service.observe(f.f.scope).availableAt());verifyNoInteractions(clock);assertEquals(2,f.f.f.data.nativeData().fixture().f().sends);assertTrue(available.toString().contains("redacted"));}
 @Test void QueuedBodyAndUnknownOrMissingSourceDaysNeverBecomeSuccessfulNoUpdate()throws Exception{var day=new ReportDailyPreparationIntegrationTest(){@Override boolean mysql(){return ReportNoUpdateProofTest.this.mysql();}};day.setup();var prepared=day.prepare();var base=day.f.data.nativeData().fixture().f();var actual=new ReportNoUpdateProofService(base.source,day.originals,base.writes,base.tx,Clock.fixed(prepared.receipt().recordedAt().plusSeconds(1),ZoneOffset.UTC));assertNull(actual.observe(day.scope));assertNull(actual.find(day.scope));day.setup();base=day.f.data.nativeData().fixture().f();base.jdbc.update("DELETE FROM jobs WHERE target_type='content_availability'");var unknown=day.prepare();assertEquals("no_input",unknown.input().state());assertFalse(unknown.input().missing().isEmpty());actual=new ReportNoUpdateProofService(base.source,day.originals,base.writes,base.tx,Clock.fixed(unknown.receipt().recordedAt().plusSeconds(1),ZoneOffset.UTC));assertNull(actual.observe(day.scope));assertEquals(0L,base.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='report_no_update_first'",Long.class));}
 @Test void RealFirstCannotBeBackdatedOrForgedAndNativeFailureRollsBackOnlyObservation()throws Exception{setup();clock=Clock.fixed(f.original.receipt().recordedAt().minusNanos(1000),ZoneOffset.UTC);compose();assertThrows(RuntimeException.class,()->service.observe(f.f.scope));assertNull(service.find(f.f.scope));clock=Clock.fixed(f.original.receipt().recordedAt().plusSeconds(1),ZoneOffset.UTC);compose();var base=f.f.f.data.nativeData().fixture().f();base.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_proven_first_failure CHECK(target_type IS NULL OR target_type<>'report_no_update_first')");assertThrows(RuntimeException.class,()->service.observe(f.f.scope));assertEquals(f.original,f.f.originals.find(f.f.scope));assertNull(service.find(f.f.scope));}
 @Test void WholeOriginalProofAndIssuerTransactionsAreMandatoryForNoUpdateAuthority()throws Exception{setup();var available=service.observe(f.f.scope);var base=f.f.f.data.nativeData().fixture().f();var other=new ReportNoUpdateProofService(base.source,f.f.originals,base.writes,base.tx,clock);assertThrows(RuntimeException.class,()->f.f.f.rr(()->other.verifyObserved(available)));assertThrows(RuntimeException.class,()->service.verifyObserved(available));assertThrows(RuntimeException.class,()->f.f.f.rr(()->service.observe(f.f.scope)));base.jdbc.update("UPDATE jobs SET call_count=1 WHERE id=?",f.original.input().ownerId());assertThrows(RuntimeException.class,()->service.find(f.f.scope));var source=mock(javax.sql.DataSource.class);var orig=mock(ReportPreparedInputService.class);var write=mock(SharedWriteExecutor.class);var tx=mock(org.springframework.transaction.PlatformTransactionManager.class);var cold=mock(Clock.class);new ReportNoUpdateProofService(source,orig,write,tx,cold);verifyNoInteractions(source,orig,write,tx,cold);}
}
